rule.example:
// 反例
@Transactional
private void insert(User u) { }          // private：代理失效
@Transactional
public static void batchInsert() { }    // static：代理失效
@Transactional
public final void update(User u) { }    // final：CGLIB 无法覆盖
// 正例
@Transactional(rollbackFor = Exception.class)
public void insert(User u) { }          // public 非 final 非 static

property.value:
(: 只匹配方法声明上的 @Transactional，避免构造器/字段上的无意义注解误报 :)
//MethodDeclaration/ModifierList/Annotation[
    pmd-java:typeIs('org.springframework.transaction.annotation.Transactional')
    and not(AnnotationMemberList/MemberValuePair[@Name='rollbackFor' or @Name='rollbackForClassName'])
]

rule.example:
// 反例（受检异常不回滚）
@Transactional
public void upload() throws IOException { throw new IOException("fail"); }  // 提交不回滚
// 正例
@Transactional(rollbackFor = Exception.class)
public void upload() throws IOException { ... }

// 反例（SpringBoot 3.x 已废弃）
public ListenableFuture<String> sendAsync() { ... }
// 正例
public CompletableFuture<String> sendAsync() { ... }

property.value:
//MethodDeclaration[
    ModifierList/Annotation[pmd-java:typeIs('org.springframework.scheduling.annotation.Async')]
    and TypeResult[
        not(PrimitiveType[@Kind='void'])
        and not(ClassType[
            pmd-java:typeIs('java.util.concurrent.Future')
            or pmd-java:typeIs('java.util.concurrent.CompletableFuture')
        ])
    ]
]
